def luhn_valid(s):
    s_clean = s.replace(' ', '')
    if not s_clean.isdigit():
        return False
    if len(s_clean) < 2:
        return False
    digits = [int(c) for c in s_clean]
    total = 0
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:
            doubled = d * 2
            if doubled > 9:
                doubled -= 9
            total += doubled
        else:
